selector_to_html = {"a[href=\"#build-a-circuit\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Build a circuit<a class=\"headerlink\" href=\"#build-a-circuit\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">n_qubits</span></code> is the preferred public spelling for circuit size. Positional construction, <code class=\"docutils literal notranslate\"><span class=\"pre\">n_wires=</span></code>, and Qiskit-compatible <code class=\"docutils literal notranslate\"><span class=\"pre\">num_qubits</span></code> remain available, and conflicting aliases fail during construction instead of being resolved silently.</p><p>Generated gate methods keep their concise positional form and also accept semantic qubit keywords: <code class=\"docutils literal notranslate\"><span class=\"pre\">h(0)</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">h(qubit=0)</span></code> are equivalent, <code class=\"docutils literal notranslate\"><span class=\"pre\">cx(0,</span> <span class=\"pre\">1)</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">cx(control=0,</span> <span class=\"pre\">target=1)</span></code> are equivalent, and symmetric two-qubit gates take <code class=\"docutils literal notranslate\"><span class=\"pre\">qubit1=</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">qubit2=</span></code>.</p>", "a[href=\"#plan-then-run\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Plan, then run<a class=\"headerlink\" href=\"#plan-then-run\" title=\"Link to this heading\">#</a></h2><p>A plan records the canonical IR, resolved execution semantics, compiler pipeline, required environment, and the selected decision under one SHA-256 identity. Passing a plan to <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.run</span></code> executes exactly that plan: there is no replanning, recompilation, or silent fallback, and a JSON round trip verifies every fingerprint before execution.</p><p>An existing plan is closed to semantic overrides. Passing <code class=\"docutils literal notranslate\"><span class=\"pre\">options</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">measurements</span></code>, or <code class=\"docutils literal notranslate\"><span class=\"pre\">noise_model</span></code> together with a plan raises <code class=\"docutils literal notranslate\"><span class=\"pre\">TypeError</span></code>, and an incompatible environment or world size fails before kernel launch.</p>", "a[href=\"#build-and-run\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Build and Run<a class=\"headerlink\" href=\"#build-and-run\" title=\"Link to this heading\">#</a></h1><h2>Build a circuit<a class=\"headerlink\" href=\"#build-a-circuit\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">n_qubits</span></code> is the preferred public spelling for circuit size. Positional construction, <code class=\"docutils literal notranslate\"><span class=\"pre\">n_wires=</span></code>, and Qiskit-compatible <code class=\"docutils literal notranslate\"><span class=\"pre\">num_qubits</span></code> remain available, and conflicting aliases fail during construction instead of being resolved silently.</p><p>Generated gate methods keep their concise positional form and also accept semantic qubit keywords: <code class=\"docutils literal notranslate\"><span class=\"pre\">h(0)</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">h(qubit=0)</span></code> are equivalent, <code class=\"docutils literal notranslate\"><span class=\"pre\">cx(0,</span> <span class=\"pre\">1)</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">cx(control=0,</span> <span class=\"pre\">target=1)</span></code> are equivalent, and symmetric two-qubit gates take <code class=\"docutils literal notranslate\"><span class=\"pre\">qubit1=</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">qubit2=</span></code>.</p>", "a[href=\"#request-measurements\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Request measurements<a class=\"headerlink\" href=\"#request-measurements\" title=\"Link to this heading\">#</a></h2><p>Pauli products use <code class=\"docutils literal notranslate\"><span class=\"pre\">@</span></code>; Hamiltonian sums and real coefficients use ordinary arithmetic. The public output factories are <code class=\"docutils literal notranslate\"><span class=\"pre\">expectation</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">probabilities</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">samples</span></code>, and <code class=\"docutils literal notranslate\"><span class=\"pre\">counts</span></code>. Probabilities and expectations are exact by default; <code class=\"docutils literal notranslate\"><span class=\"pre\">samples</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">counts</span></code> require a positive shot count. Use <code class=\"docutils literal notranslate\"><span class=\"pre\">result.measurement(index_or_name)</span></code> for a specific request, <code class=\"docutils literal notranslate\"><span class=\"pre\">result.statevector()</span></code> when a statevector is required, and <code class=\"docutils literal notranslate\"><span class=\"pre\">result.native()</span></code> only when intentionally depending on an unstable backend-native object.</p>", "a[href=\"#record-and-replay\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Record and replay<a class=\"headerlink\" href=\"#record-and-replay\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">Circuit(...,</span> <span class=\"pre\">record_op=True)</span></code> keeps the instruction list that produced a state, and the same circuit can be exported for tools outside FlagQuantum (see <a class=\"reference internal\" href=\"compile-and-target.html\"><span class=\"std std-doc\">Compile and Target</span></a>). A recorded program is the input to deployment packaging, so a circuit that was trained, compiled, or submitted always has an inspectable source.</p>", "a[href=\"#handle-errors\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Handle errors<a class=\"headerlink\" href=\"#handle-errors\" title=\"Link to this heading\">#</a></h2><p>All categories inherit <code class=\"docutils literal notranslate\"><span class=\"pre\">FlagQuantumError</span></code> and a compatible Python built-in exception. Wrong Python types and unknown keyword arguments continue to raise <code class=\"docutils literal notranslate\"><span class=\"pre\">TypeError</span></code>.</p>", "a[href=\"compile-and-target.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Compile and Target<a class=\"headerlink\" href=\"#compile-and-target\" title=\"Link to this heading\">#</a></h1><h2>Target-independent optimisation<a class=\"headerlink\" href=\"#target-independent-optimisation\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">optimize</span></code> returns a new <code class=\"docutils literal notranslate\"><span class=\"pre\">CircuitIR</span></code>, leaves the input unchanged, and applies canonical rewrites to a fixed point. It never selects or invokes an execution backend. A runnable example is <code class=\"docutils literal notranslate\"><span class=\"pre\">python</span> <span class=\"pre\">-m</span> <span class=\"pre\">examples.compiler_optimize</span></code>.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
